{
  "name": "@privacypillar/pii-shield-opencode",
  "version": "0.0.1-alpha.6",
  "publishConfig": {
    "access": "public"
  },
  "type": "module",
  "main": "index.js",
  "module": "index.js",
  "exports": {
    ".": "./index.js"
  },
  "description": "Privacy-first PII and secret detection plugin for OpenCode. Blocks API keys, passwords, SSNs, credit cards, and 25+ other sensitive data types from reaching any LLM. All detection is local — no data ever leaves your machine.",
  "keywords": [
    "opencode",
    "privacy",
    "pii",
    "secrets",
    "security",
    "gdpr",
    "hipaa",
    "ai-safety"
  ],
  "author": {
    "name": "PrivacyPillar",
    "url": "https://github.com/privacypillar/pii-shield"
  },
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "https://github.com/privacypillar/pii-shield.git"
  },
  "homepage": "https://privacypillar.github.io/pii-shield",
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "postinstall": "node postinstall.js",
    "build": "vite build && npm pack",
    "dev": "vite build --watch",
    "build:plugin": "vite build",
    "pack": "npm pack",
    "test": "node --test test/*.test.js"
  },
  "files": [
    "index.js",
    "postinstall.js",
    "plugin/"
  ],
  "dependencies": {
    "@faker-js/faker": "^9.9.0",
    "@xenova/transformers": "^2.17.2"
  },
  "devDependencies": {
    "vite": "^6.4.1"
  }
}

{
  "type": "module",
  "description": "OpenCode PII Shield plugin — no external dependencies required"
}
